import React, { useState, useEffect } from 'react';



import { Link, useNavigate } from 'react-router-dom';



import { getFeaturedProducts, getProductCategories, login } from '../services/api';

import { createSimpleSubscription, getUserSubscriptions } from '../services/simpleApi';



import { isAuthenticated, getAuthData, saveAuthData } from '../util/auth';



import ProductCard from '../components/ProductCard';
import ModernPlanCard from '../components/ModernPlanCard';



import Toast from '../components/Toast';



import { useTheme } from '../context/ThemeContext';
import { useAuth } from '../context/AuthContext';

import { useSocket } from '../context/SocketContext';

import useToast from '../hooks/useToast';

import SimpleQRCode from '../components/SimpleQRCode';



const Home = () => {



  const [featuredProducts, setFeaturedProducts] = useState([]);



  const [categories, setCategories] = useState([]);



  const [loading, setLoading] = useState(true);



  const [currentSlide, setCurrentSlide] = useState(0);



  const [showScrollTop, setShowScrollTop] = useState(false);



  const [selectedPlan, setSelectedPlan] = useState(null);



  const [subscriptionModal, setSubscriptionModal] = useState(false);



  const [loadingSubscription, setLoadingSubscription] = useState(false);

  const [qrPlan, setQrPlan] = useState(null);

  const [showPaymentConfirmed, setShowPaymentConfirmed] = useState(false);
  const [showPaymentFailed, setShowPaymentFailed] = useState(false);
  const [showRewardsLoginModal, setShowRewardsLoginModal] = useState(false);
  const [rewardsLoginForm, setRewardsLoginForm] = useState({ email: '', password: '' });
  const [rewardsLoginError, setRewardsLoginError] = useState('');
  const [rewardsLoginLoading, setRewardsLoginLoading] = useState(false);

  const [userHasSubscription, setUserHasSubscription] = useState(false);

  const navigate = useNavigate();

  const { socket, joinUserRoom } = useSocket();



  const [chatPopup, setChatPopup] = useState(false);



  const [featureSlide, setFeatureSlide] = useState(0);



  const [selectedCategory, setSelectedCategory] = useState(null);



  const [viewMode, setViewMode] = useState('grid');

  // Health Calculator State
  const [calculatorAge, setCalculatorAge] = useState('Adults (19-50 years)');
  const [calculatorActivity, setCalculatorActivity] = useState('Moderately Active');
  const [calculatedRequirements, setCalculatedRequirements] = useState({
    milk: '500ml',
    paneer: '50g',
    yogurt: '200g'
  });

  const { isDarkMode } = useTheme();
  const { login: authLogin } = useAuth();

  const handleRewardsClick = () => {
    if (isAuthenticated()) {
      navigate('/account');
      return;
    }
    setRewardsLoginError('');
    setShowRewardsLoginModal(true);
  };

  const handleOpenLoginPopup = () => {
    const currentPath = window.location.pathname + window.location.search;
    const intendedUrl = localStorage.getItem('intendedUrl');
    if (!intendedUrl || intendedUrl === '/login') {
      localStorage.setItem('intendedUrl', currentPath);
    }
    setRewardsLoginError('');
    setShowRewardsLoginModal(true);
  };

  const handleRewardsLoginChange = (e) => {
    const { name, value } = e.target;
    setRewardsLoginForm(prev => ({
      ...prev,
      [name]: value
    }));
    setRewardsLoginError('');
  };

  const handleRewardsLoginSubmit = async (e) => {
    e.preventDefault();
    if (!rewardsLoginForm.email || !rewardsLoginForm.password) {
      setRewardsLoginError('Please fill in both email and password');
      return;
    }

    try {
      setRewardsLoginLoading(true);
      setRewardsLoginError('');
      const res = await login(rewardsLoginForm);
      saveAuthData(res.data.token, res.data);
      // Notify AuthContext so navbar and other components update
      try {
        authLogin(res.data);
      } catch (e) {
        console.warn('Auth context login notifier failed', e);
      }
      setShowRewardsLoginModal(false);

      const intendedUrl = localStorage.getItem('intendedUrl');
      if (intendedUrl && intendedUrl !== '/login') {
        localStorage.removeItem('intendedUrl');
        navigate(intendedUrl, { replace: true });
      }
    } catch (error) {
      setRewardsLoginError(error.response?.data?.message || 'Login failed. Please try again.');
    } finally {
      setRewardsLoginLoading(false);
    }
  };




  const { toasts, removeToast, success } = useToast();

  // Health Calculator Function
  const calculateDailyRequirements = () => {
    let milkAmount = 500;
    let paneerAmount = 50;
    let yogurtAmount = 200;

    // Adjust based on age group
    if (calculatorAge.includes('Children')) {
      milkAmount = 400;
      paneerAmount = 30;
      yogurtAmount = 150;
    } else if (calculatorAge.includes('Pre-teens')) {
      milkAmount = 500;
      paneerAmount = 40;
      yogurtAmount = 180;
    } else if (calculatorAge.includes('Teens')) {
      milkAmount = 600;
      paneerAmount = 50;
      yogurtAmount = 200;
    } else if (calculatorAge.includes('Seniors')) {
      milkAmount = 400;
      paneerAmount = 40;
      yogurtAmount = 150;
    }

    // Adjust based on activity level
    if (calculatorActivity.includes('Sedentary')) {
      milkAmount = Math.round(milkAmount * 0.8);
      paneerAmount = Math.round(paneerAmount * 0.8);
      yogurtAmount = Math.round(yogurtAmount * 0.8);
    } else if (calculatorActivity.includes('Very Active')) {
      milkAmount = Math.round(milkAmount * 1.2);
      paneerAmount = Math.round(paneerAmount * 1.2);
      yogurtAmount = Math.round(yogurtAmount * 1.2);
    }

    setCalculatedRequirements({
      milk: `${milkAmount}ml`,
      paneer: `${paneerAmount}g`,
      yogurt: `${yogurtAmount}g`
    });

    success('Daily requirements calculated successfully!', 2000);
  };

  useEffect(() => {

    fetchData();



    // Handle scroll events



    const handleScroll = () => {



      setShowScrollTop(window.scrollY > 50);



    };



    window.addEventListener('scroll', handleScroll);



    



    // Auto-rotate hero slides



    const heroInterval = setInterval(() => {



      setCurrentSlide((prev) => (prev + 1) % 3);



    }, 4000);



    



    // Auto-rotate feature slides



    const featureInterval = setInterval(() => {



      setFeatureSlide((prev) => (prev + 1) % 3);



    }, 3000);



    



    return () => {



      clearInterval(heroInterval);



      clearInterval(featureInterval);



      window.removeEventListener('scroll', handleScroll);



    };



  }, []);



  



  // Lock body scroll when popup is open



  useEffect(() => {



    if (subscriptionModal || showPaymentConfirmed || showPaymentFailed || showRewardsLoginModal) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }



    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [subscriptionModal, showPaymentConfirmed, showPaymentFailed, showRewardsLoginModal]);

  // Socket listener for subscription confirmation
  useEffect(() => {
    if (!socket) {
      console.log('❌ Socket not available');
      return;
    }

    console.log('🔌 Setting up socket listener for subscriptionConfirmed');

    // Join user room for real-time notifications
    const authData = getAuthData();
    if (authData && authData.user && authData.user._id) {
      console.log('👤 Joining user room:', authData.user._id);
      joinUserRoom(authData.user._id);
    } else {
      console.log('❌ No auth data or user ID available');
    }

    const handleSubscriptionConfirmed = (data) => {
      console.log('✅ Subscription confirmed event received:', data);
      // Close QR modal
      setQrPlan(null);
      // Close subscription modal
      setSubscriptionModal(false);
      setSelectedPlan(null);
      // Show modern glass popup
      setShowPaymentConfirmed(true);
      // Close popup after 6 seconds, then navigate
      setTimeout(() => {
        setShowPaymentConfirmed(false);
        setTimeout(() => {
          navigate('/subscriptions', { state: { scrollToActive: true } });
        }, 300);
      }, 6000);
    };

    const handleSubscriptionFailed = (data) => {
      console.log('❌ Subscription payment failed:', data);
      // Close QR modal
      setQrPlan(null);
      // Close subscription modal
      setSubscriptionModal(false);
      setSelectedPlan(null);
      // Show failed payment popup
      setShowPaymentFailed(true);
      // Auto close after 6 seconds, then navigate to subscriptions failed section
      setTimeout(() => {
        setShowPaymentFailed(false);
        navigate('/subscriptions', { state: { scrollToFailed: true } });
      }, 6000);
    };

    socket.on('subscriptionConfirmed', handleSubscriptionConfirmed);
    socket.on('subscriptionFailed', handleSubscriptionFailed);

    return () => {
      socket.off('subscriptionConfirmed', handleSubscriptionConfirmed);
      socket.off('subscriptionFailed', handleSubscriptionFailed);
    };
  }, [socket, joinUserRoom, navigate]);



  // Check if authenticated user already has a subscription



  useEffect(() => {



    const checkUserSubscription = async () => {



      if (!isAuthenticated()) return;



      try {



        const res = await getUserSubscriptions();



        if (res.data && Array.isArray(res.data)) {



          const hasActive = res.data.some(sub => sub.status === 'active');



          setUserHasSubscription(hasActive);



        }



      } catch (error) {



        console.error('Error checking user subscriptions:', error);



      }



    };



    checkUserSubscription();



    // Listen for subscription changes via socket
    if (socket) {
      const handleSubChange = () => {
        checkUserSubscription();
      };
      socket.on('subscriptionConfirmed', handleSubChange);
      socket.on('subscriptionCancelled', handleSubChange);
      return () => {
        socket.off('subscriptionConfirmed', handleSubChange);
        socket.off('subscriptionCancelled', handleSubChange);
      };
    }



  }, [socket]);







  const fetchData = async () => {



    try {



      setLoading(true);



      const [featuredRes, categoriesRes] = await Promise.all([



        getFeaturedProducts(),



        getProductCategories()



      ]);



      setFeaturedProducts(featuredRes.data);



      setCategories(categoriesRes.data);



    } catch (error) {



      console.error('Error fetching data:', error);



    } finally {



      setLoading(false);



    }



  };



  const scrollToTop = () => {



    window.scrollTo({



      top: 0,



      behavior: 'smooth'



    });



  };



  const handleSubscribe = async (planType) => {



    if (!userAuthenticated) {



      // Redirect to login if not authenticated



      window.location.href = '/login';



      return;



    }



    setSelectedPlan(planType);



    setSubscriptionModal(true);



  };



  const createSubscriptionHandler = async () => {



    if (!selectedPlan) return;



    



    try {



      setLoadingSubscription(true);



      



      const planDetails = getPlanDetails(selectedPlan);
      
      const subscriptionData = {
        planType: selectedPlan,
        planName: planDetails.name,
        price: planDetails.price
      };



      



      const response = await createSimpleSubscription(subscriptionData);



      



      if (response.status === 201 || response.status === 200) {

        console.log('✅ Subscription created successfully');

        

        // Show QR code modal (subscription modal stays open behind it)
        setQrPlan(planDetails);



      } else {



        // Error - show error message

        // Error handled by toast notification

      }



    } catch (error) {



      console.error('Subscription error:', error);



      // Error handled by toast notification



    } finally {



      setLoadingSubscription(false);



    }



  };



  const getPlanDetails = (planType) => {



    const plans = {



      daily: {



        name: 'Daily Plan',



        price: 29,



        duration: 'day',



        features: [



          '500ml Fresh Milk Daily',



          '6:00 AM - 7:00 AM Delivery',



          'Pause Anytime',



          'Free Delivery'



        ]



      },



      weekly: {



        name: 'Weekly Plan',



        price: 189,



        duration: 'week',



        features: [



          '3.5L Milk Per Week',



          'Flexible Delivery Days',



          '10% Discount',



          'Free Delivery'



        ]



      },



      monthly: {



        name: 'Monthly Plan',



        price: 799,



        duration: 'month',



        features: [



          '15L Milk Per Month',



          'Custom Schedule',



          '20% Discount',



          'Free Delivery + Priority'



        ]



      }



    };



    



    return plans[planType] || plans.daily;



  };



  const userAuthenticated = isAuthenticated();



  return (



      <div className="fade-in">



      





      {/* Modern Hero Section - Completely Seamless */}



      <section className="relative min-h-screen flex items-center justify-center overflow-hidden">



        {/* Background - Plain solid color only */}



        {/* Main Content */}



        <div className="text-center px-6 max-w-5xl mx-auto">



          <div className="space-y-12">



            {/* Time-based Greeting or Badge */}



            {(() => {



              const authData = getAuthData();



              const user = authData.user;



              if (user && user.name) {



                const hour = new Date().getHours();



                let greeting = 'Good Evening';



                let emoji = '🌙';



                if (hour >= 5 && hour < 12) { greeting = 'Good Morning'; emoji = '☀️'; }



                else if (hour >= 12 && hour < 17) { greeting = 'Good Afternoon'; emoji = '⛅'; }



                return (



                  <div className="mb-4">



                    <div className={`text-sm font-semibold tracking-widest uppercase mb-1 ${isDarkMode ? 'text-slate-500' : 'text-gray-400'}`}>



                      {emoji} {greeting}



                    </div>



                    <div className={`text-2xl md:text-3xl font-light ${isDarkMode ? 'text-slate-300' : 'text-gray-600'}`}>



                      Welcome back, <span className="font-bold bg-gradient-to-r from-blue-500 to-emerald-500 bg-clip-text text-transparent">{user.name.split(' ')[0]}</span>



                    </div>



                  </div>



                );



              }



              return (



                <div className={`inline-flex items-center gap-3 text-sm font-medium mb-8 ${isDarkMode ? 'text-slate-400' : 'text-gray-500'}`}>



                  <span className="relative flex h-2 w-2">



                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>



                    <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>



                  </span>



                  Fresh Milk Delivered Daily



                </div>



              );



            })()}



            {/* Headline */}



            <h1 className={`text-4xl md:text-5xl lg:text-6xl font-extrabold tracking-tight leading-[1.1] mb-6 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>



              Pure Dairy



              <span className="block bg-gradient-to-r from-blue-500 via-purple-500 to-emerald-500 bg-clip-text text-transparent">



                Delivered Fresh



              </span>



            </h1>



            {/* Subtitle */}



            <p className={`text-lg md:text-xl max-w-2xl mx-auto mb-10 leading-relaxed ${isDarkMode ? 'text-slate-400' : 'text-gray-500'}`}>



              Farm-fresh milk, organic cheese, and premium dairy essentials delivered straight to your doorstep every morning.



              Quality you can taste, trust you can count on.



            </p>



            {/* Buttons Row - No borders on secondary */}



            <div className="flex flex-col sm:flex-row gap-4 justify-center items-center mb-16">



              <Link



                to="/products"



                className="group relative px-8 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white font-semibold rounded-full overflow-hidden transition-transform hover:scale-105 shadow-lg shadow-blue-500/25"



              >



                <span className="relative z-10 flex items-center gap-2">



                  Order Now



                  <svg className="w-5 h-5 transition-transform group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">



                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />



                  </svg>



                </span>



              </Link>



              {!userAuthenticated && (

                <button

                  type="button"

                  onClick={handleOpenLoginPopup}

                  className="group relative px-8 py-4 bg-gradient-to-r from-green-600 to-emerald-600 text-white font-semibold rounded-full overflow-hidden transition-transform hover:scale-105 shadow-lg shadow-green-500/25"

                >

                  <span className="relative z-10 flex items-center gap-2">

                    Get Started

                    <svg className="w-5 h-5 transition-transform group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />

                    </svg>

                  </span>

                </button>

              )}




            </div>



            {!userAuthenticated && (



              <div className="flex flex-col sm:flex-row gap-8 justify-center items-center mb-16">



                <div className="text-center">



                  <div className={`text-3xl md:text-4xl font-bold ${isDarkMode ? 'text-slate-300' : 'text-gray-600'}`}>15K+</div>



                  <div className={`text-sm mt-1 ${isDarkMode ? 'text-slate-600' : 'text-gray-400'}`}>Happy Families</div>



                </div>



                <div className="text-center">



                  <div className={`text-3xl md:text-4xl font-bold ${isDarkMode ? 'text-slate-300' : 'text-gray-600'}`}>50+</div>



                  <div className={`text-sm mt-1 ${isDarkMode ? 'text-slate-600' : 'text-gray-400'}`}>Dairy Products</div>



                </div>



                <div className="text-center">



                  <div className={`text-3xl md:text-4xl font-bold ${isDarkMode ? 'text-slate-300' : 'text-gray-600'}`}>4.9</div>



                  <div className={`text-sm mt-1 ${isDarkMode ? 'text-slate-600' : 'text-gray-400'}`}>Customer Rating</div>



                </div>



              </div>



            )}



          </div>



        </div>



      </section>



      <div className="h-20"></div>



      {/* Modern Categories Section */}



      <section className="mb-16 relative pt-12">



        {/* Modern Section Header */}



        <div className="text-center mb-12">



          <div className="inline-block relative group">



            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">



                Shop by Category



              </span>



            </h2>



            {/* Animated Underline - Like Featured Products */}



            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>



          </div>



          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>



            Explore our wide range of fresh dairy products



          </p>



        </div>



        {/* Modern Grid Layout */}



        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-8">



          {categories.map((category) => (



            <Link



              key={category}



              to={`/products?category=${category}`}



              className="group relative block"



            >



              {/* Ultra-Premium Card Container */}



              <div className="relative p-10 text-center bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-black dark:via-black dark:to-black rounded-[3rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500 transition-all duration-1000 transform hover:scale-105 hover:shadow-4xl hover:shadow-primary-500/20 overflow-hidden group">



                



                {/* Multi-Layer Animated Background */}



                <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-1000">



                  {/* Base Gradient */}



                  <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-transparent to-secondary-500/10 animate-gradient-shift"></div>



                  



                  {/* Sliding Light Effect */}



                  <div className="absolute inset-0">



                    <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-slide"></div>



                    <div className="absolute top-1/3 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-primary-200/20 to-transparent animate-slide animation-delay-2"></div>



                    <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-secondary-200/20 to-transparent animate-slide animation-delay-4"></div>



                  </div>



                  



                                  </div>



                



                {/* Luxury Glow Effect */}



                <div className="absolute inset-0 bg-gradient-to-br from-primary-500/20 via-secondary-500/15 to-primary-500/20 rounded-[3rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-3xl"></div>



                



                {/* Glass Morphism Overlay */}



                <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all duration-1000"></div>



                



                {/* Icon Container with Ultra-Advanced Effects */}



                <div className="relative z-10 mb-8">



                  <div className="w-24 h-24 mx-auto relative">



                    {/* Multi-Layer Icon Background */}



                    <div className="absolute inset-0 bg-gradient-to-br from-primary-100 via-white to-secondary-100 dark:from-black dark:via-black dark:to-black rounded-[2.5rem] flex items-center justify-center transform transition-all duration-1000 group-hover:scale-125 group-hover:rotate-12 shadow-2xl border-2 border-white/50 dark:border-gray-700/50">



                      {/* Inner Glow */}



                      <div className="absolute inset-2 bg-gradient-to-br from-white/50 to-transparent rounded-[2rem]"></div>



                      



                      {/* Icon with Advanced Effects */}



                      <span className="text-5xl transform transition-all duration-700 group-hover:scale-150 group-hover:rotate-180 drop-shadow-2xl relative z-10">



                        {category === 'milk' && '🥛'}



                        {category === 'butter' && '🧈'}



                        {category === 'buttermilk' && '🫙'}



                        {category === 'cheese' && '🧀'}



                        {category === 'cream' && '🍦'}



                        {category === 'curd' && '🥣'}



                        {category === 'ghee' && '🍯'}



                        {category === 'lassi' && '🥤'}



                        {category === 'paneer' && '🧊'}



                        {category === 'yogurt' && '🍶'}



                        {category === 'sweets' && '🍬'}



                        {category === 'cake' && '🍰'}



                      </span>



                    </div>



                    



                    {/* Ultra-Advanced Icon Glow */}



                    <div className="absolute inset-0 bg-gradient-to-br from-primary-400/60 via-secondary-400/40 to-primary-400/60 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-2xl"></div>



                    



                                      </div>



                </div>



                



                {/* Ultra-Enhanced Category Name */}



                <div className="relative z-10">



                  <h3 className={`font-black text-2xl capitalize transition-all duration-700 ${isDarkMode ? 'text-white group-hover:text-primary-300' : 'text-gray-800 group-hover:text-primary-600'}`}>



                    {category}



                  </h3>



                  <div className="mt-3 h-1 bg-gradient-to-r from-transparent via-primary-500 to-transparent transform scale-x-0 group-hover:scale-x-100 transition-all duration-700 rounded-full"></div>



                  <div className="mt-2 text-sm font-medium opacity-0 group-hover:opacity-100 transition-opacity duration-700 text-primary-600 dark:text-primary-400">



                    Explore Products →



                  </div>



                </div>



                



                                



                {/* Premium Card Edge Effects */}



                <div className="absolute inset-0 rounded-[3rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000"></div>



                <div className="absolute inset-1 rounded-[3rem] border border-transparent group-hover:border-white/30 transition-all duration-1000"></div>



                



                {/* Hover Reveal Effect */}



                <div className="absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-primary-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-1000 transform translate-y-full group-hover:translate-y-0"></div>



              </div>



            </Link>



          ))}



        </div>



      </section>



      {/* Modern Featured Products Section */}



      <section className="mb-16">



        {/* Modern Section Header */}



        <div className="text-center mb-12">



          <div className="inline-block relative group">



