                  <div className="absolute inset-0 bg-gradient-to-r from-primary-500/30 via-secondary-500/30 to-primary-500/30 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>

                </button>

              </div>

            </div>



          </div>

          </div>



            ) : null

          })()}

        </>

