                    }`}>



                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



                        How do I track my order?



                      </h5>



                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>



                        Click on "Track my order" above or check your email for tracking details.



                      </p>



                    </div>



                    <div className={`p-2 rounded-lg text-xs ${



                      isDarkMode ? 'bg-gray-700' : 'bg-white'



                    }`}>



                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



                        What are your delivery hours?



                      </h5>



                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>



                        We deliver 6 AM to 10 PM, 7 days a week.



                      </p>



                    </div>



                    <div className={`p-2 rounded-lg text-xs ${



                      isDarkMode ? 'bg-gray-700' : 'bg-white'



                    }`}>



                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



                        How do I cancel my subscription?



                      </h5>



                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>



                        Go to Account Settings and select "Manage Subscription".



                      </p>



                    </div>



                  </div>



                </div>



              </div>



            </div>



          </div>



        </div>



      </>

    )}



      {/* Scroll to Top Button - Modern Design */}



      {showScrollTop && !chatPopup && !subscriptionModal && !showPaymentConfirmed && !showPaymentFailed && (
        <button
          onClick={scrollToTop}
          className="fixed bottom-2 right-6 px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-full shadow-2xl hover:shadow-3xl hover:scale-110 transition-all duration-300 flex items-center space-x-2 group"
          style={{ zIndex: 99999 }}
        >



          <svg 

            className="w-6 h-6 transform transition-transform duration-300 group-hover:-translate-y-1 flex-shrink-0" 
            fill="currentColor" 

            stroke="currentColor" 

            viewBox="0 0 24 24"

          >

            <path 

              strokeLinecap="round" 

              strokeLinejoin="round" 

              strokeWidth={2} 

              d="M5 10l7-7m0 0l7 7m-7-7v18" 

            />

          </svg>


          {/* Glow Effect */}

          <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-purple-400 rounded-full opacity-0 group-hover:opacity-30 transition-opacity duration-300 blur-xl"></div>

        </button>

            )}

    </div>

    

  );

};



export default Home;
